/**
 * New User Onboarding Flow
 *
 * This flow handles the complete onboarding process for new users:
 * 1. Sends a welcome notification to the new user
 * 2. Assigns a laptop based on availability
 * 3. Assigns a desk at their closest office location
 * 4. Sends confirmation notification with assignment details
 *
 * Triggers when a new user record is created in the sys_user table
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const newUserOnboardingFlow = Flow(
    {
        $id: Now.ID['new_user_onboarding_flow'],
        name: 'New User Onboarding Flow',
        description:
            'Complete onboarding process for new users including welcome email, laptop assignment, and desk assignment',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['new_user_created_trigger'] },
        {
            table: 'sys_user',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (params) => {
        // Step 1: Send welcome notification to the new user
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_welcome_notification'],
                annotation: 'Send welcome notification to new user',
            },
            {
                record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                notification: 'new_user_welcome_notification',
            }
        )

        // Step 2: Assign a laptop to the new user
        const availableLaptops = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_available_laptops'],
                annotation: 'Find available laptops in inventory',
            },
            {
                table: 'alm_hardware',
                conditions: 'install_status=1^assigned_to=NULL',
                max_results: 1,
                sort_column: 'sys_created_on',
                sort_type: 'sort_desc',
            }
        )

        // Check if laptops are available
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(availableLaptops.Count, 'integer')}>0`,
                annotation: 'Check if laptops are available for assignment',
                $id: Now.ID['check_laptop_availability'],
            },
            () => {
                // Update the first available laptop with user assignment
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['assign_laptop_to_user'],
                        annotation: 'Assign laptop to new user',
                    },
                    {
                        table_name: 'alm_hardware',
                        record: `${wfa.dataPill(availableLaptops.Records, 'reference')}`,
                        values: TemplateValue({
                            assigned_to: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                            install_status: 2,
                        }),
                    }
                )
            }
        )

        wfa.flowLogic.else(
            {
                annotation: 'Handle no laptops available scenario',
                $id: Now.ID['handle_no_laptops'],
            },
            () => {
                // Log warning if no laptops available
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_no_laptops'],
                        annotation: 'Log laptop shortage warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `No laptops available for assignment to user: ${wfa.dataPill(params.trigger.current.name, 'string')}`,
                    }
                )

                // Create incident for IT to handle
                wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_laptop_shortage_incident'],
                        annotation: 'Create incident for laptop shortage',
                    },
                    {
                        table_name: 'incident',
                        values: TemplateValue({
                            short_description: `No laptop available for new user: ${wfa.dataPill(params.trigger.current.name, 'string')}`,
                            priority: 2,
                            urgency: 2,
                            category: 'Hardware',
                            caller_id: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        }),
                    }
                )
            }
        )

        // Step 3: Assign a desk at the user's office location
        const userLocation = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_user_location'],
                annotation: 'Retrieve user office location details',
            },
            {
                table: 'cmn_location',
                conditions: `sys_id=${wfa.dataPill(params.trigger.current.location, 'reference')}`,
            }
        )

        // Look up available desks at that location
        const availableDesks = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_available_desks'],
                annotation: 'Find available desks at user location',
            },
            {
                table: 'alm_asset',
                conditions: `location=${wfa.dataPill(userLocation.Record.sys_id, 'reference')}^install_status=1^assigned_to=NULL`,
                max_results: 1,
                sort_column: 'asset_tag',
                sort_type: 'sort_asc',
            }
        )

        // Check if desks are available
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(availableDesks.Count, 'integer')}>0`,
                annotation: 'Check if desks are available for assignment',
                $id: Now.ID['check_desk_availability'],
            },
            () => {
                // Update the first available desk with user assignment
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['assign_desk_to_user'],
                        annotation: 'Assign desk to new user',
                    },
                    {
                        table_name: 'alm_asset',
                        record: `${wfa.dataPill(availableDesks.Records, 'reference')}`,
                        values: TemplateValue({
                            assigned_to: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                            install_status: 2,
                        }),
                    }
                )
            }
        )

        wfa.flowLogic.else(
            {
                annotation: 'Handle no desks available scenario',
                $id: Now.ID['handle_no_desks'],
            },
            () => {
                // Log warning if no desks available
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_no_desks'],
                        annotation: 'Log desk shortage warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `No desks available at ${wfa.dataPill(userLocation.Record.name, 'string')} for user: ${wfa.dataPill(params.trigger.current.name, 'string')}`,
                    }
                )

                // Create incident for facilities to handle
                wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_desk_shortage_incident'],
                        annotation: 'Create incident for desk shortage',
                    },
                    {
                        table_name: 'incident',
                        values: TemplateValue({
                            short_description: `No desk available for new user: ${wfa.dataPill(params.trigger.current.name, 'string')} at ${wfa.dataPill(userLocation.Record.name, 'string')}`,
                            priority: 3,
                            urgency: 3,
                            category: 'Facilities',
                            caller_id: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                        }),
                    }
                )
            }
        )

        // Step 4: Send confirmation notification with assignment details
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_assignment_confirmation'],
                annotation: 'Send equipment assignment confirmation notification',
            },
            {
                record: `${wfa.dataPill(params.trigger.current.sys_id, 'reference')}`,
                notification: 'equipment_assignment_confirmation_notification',
            }
        )
    }
)
